from collections import deque
def bfs(graph, start, goal):
    queue = deque([[start]])
    seen = {start}
    while queue:
        path = queue.popleft()
        if path[-1] == goal:
            return path
        for nb in graph[path[-1]]:
            if nb not in seen:
                seen.add(nb)
                queue.append(path + [nb])

