from collections import deque
m = int(input())
graph = {}
for _ in range(m):
    a, b = input().split()
    graph.setdefault(a, []).append(b)
    graph.setdefault(b, []).append(a)
start, goal = input().split()
queue = deque([[start]])
seen = {start}
found = None
while queue:
    path = queue.popleft()
    if path[-1] == goal:
        found = path
        break
    for nb in sorted(graph.get(path[-1], [])):
        if nb not in seen:
            seen.add(nb)
            queue.append(path + [nb])
if found:
    print(' -> '.join(found))
    print(f'steps {len(found) - 1}')
else:
    print('no path')

