import re
import sys
stop = set(input().split())
k = int(input())
text = sys.stdin.read().lower()
counts = {}
for w in re.findall(r"[a-z']+", text):
    if w not in stop:
        counts[w] = counts.get(w, 0) + 1
ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
for w, c in ranked[:k]:
    print(w, c)

